globalThis.process===void 0&&(globalThis.process={env:{},nextTick:function(e){setTimeout(e,0)},emit:function(){return!1}});import"react";import"react-dom";import"react/jsx-runtime";import"react-dom/client";var e={sender:`Gaia`,preview:`नमस्ते 👋 संपर्क करने के लिए धन्यवाद। मैं जल्द ही आपको जवाब देती हूँ…`,ageLabel:`4 घं.`},t=JSON.parse('{"demo-news-1":{"title":"Pioneer 2026: तारीख़ नोट कर लें","excerpt":"हम 8 अक्टूबर को सैन फ्रांसिस्को लौट रहे हैं। दरवाज़े 9 बजे खुलेंगे, कीनोट 10 बजे।","body":"## क्या उम्मीद करें\\n\\nइस साल का कीनोट इस बारे में है कि हमने खुले तौर पर क्या जारी किया और आगे क्या आ रहा है। लाइव डेमो, स्लाइड नहीं।\\n\\n- **Gaia का रोडमैप** - अगली दो तिमाहियों में हमारा AI किस दिशा में जा रहा है।\\n- **ग्राहकों की कहानियाँ** - तीन टीमें बताती हैं कि उन्होंने पहले जवाब का समय आधा कैसे किया।\\n- **हैंड्स-ऑन लैब** - लैपटॉप लाइए और हमारे इंजीनियरों के साथ एक फ़्लो बनाइए।\\n\\n## कैसे पहुँचें\\n\\nस्थल Pier 27 Cruise Terminal है, ठीक Embarcadero पर। सबसे नज़दीकी BART स्टेशन Embarcadero है, पानी के किनारे 12 मिनट की पैदल दूरी पर।\\n\\n## टिकट\\n\\nअर्ली-बर्ड सीटें सीमित हैं और अगले हफ़्ते उपलब्ध होंगी। मौजूदा ग्राहकों को पहले मौका मिलेगा, इसलिए अपने इनबॉक्स पर नज़र रखें।\\n\\n> व्यक्तिगत रूप से नहीं आ सकते? कीनोट का लाइव प्रसारण होगा और रिकॉर्डिंग उसी शाम यहाँ उपलब्ध होंगी।"},"demo-news-2":{"title":"अप्रैल में क्या जारी हुआ","excerpt":"तीन नए ऑटोमेशन ट्रिगर और इनबॉक्स में कहीं ज़्यादा तेज़ खोज।","body":"<p>अप्रैल एक बड़ा महीना था। जो कुछ जारी हुआ, वह एक नज़र में:</p>\\n<table>\\n<thead><tr><th>क्षेत्र</th><th>क्या बदला</th><th>यह क्यों मायने रखता है</th></tr></thead>\\n<tbody>\\n<tr><td>इनबॉक्स खोज</td><td>टाइप करते ही तुरंत नतीजे</td><td>50 हज़ार बातचीतें, 100 मि.से. से कम में</td></tr>\\n<tr><td>ऑटोमेशन</td><td>तीन नए ट्रिगर</td><td>छोड़ी गई कार्ट, दोबारा देखा गया पेज, शांत विज़िटर</td></tr>\\n<tr><td>कंपोज़र</td><td>टैब बदलने पर भी ड्राफ़्ट बचा रहता है</td><td>आधे लिखे जवाब अब नहीं खोएंगे</td></tr>\\n<tr><td>डार्क मोड</td><td>पहली बार दिखने पर सफ़ेद चमक नहीं</td><td>डार्क साइट पर साफ़ लोडिंग</td></tr>\\n</tbody>\\n</table>\\n<p>नई खोज काम करते हुए - आपके टाइप पूरा करने से पहले नतीजे आ जाते हैं:</p>\\n<img src=\\"https://picsum.photos/seed/wexio-search/1024/576\\" alt=\\"तुरंत नतीजे दिखाती इनबॉक्स खोज\\" />\\n<p>क़रीब से देखने के लिए तस्वीर पर टैप करें। कोई अनुरोध है? यहाँ जवाब दें - हम हर एक पढ़ते हैं।</p>"},"demo-news-3":{"title":"Gaia अब 28 भाषाएँ बोलती है","excerpt":"विज़िटर की भाषा अपने आप पहचानें या कोई एक तय करें। कोई अतिरिक्त सेटअप नहीं।","body":"<p>Gaia अब 28 भाषाओं में जवाब देती है, जो विज़िटर के पहले संदेश से अपने आप पहचानी जाती हैं। सबसे ज़्यादा पूछे जाने वाले सवाल:</p>\\n<details><summary>भाषा की पहचान कैसे काम करती है?</summary><p>Gaia शुरुआती संदेश पढ़ती है और उसी भाषा में जवाब देती है। अगर आपके सहायता लेख उस भाषा में हैं तो वह उनका हवाला देती है; नहीं तो वह निकटतम मेल से जवाब देती है और आपको कमी के बारे में बता देती है।</p></details>\\n<details><summary>क्या मैं सिर्फ़ एक भाषा तय कर सकता हूँ?</summary><p>हाँ। <strong>सेटिंग्स → AI → भाषा</strong> में एक भाषा तय करें, और विज़िटर कुछ भी लिखे, Gaia उसी पर टिकी रहेगी।</p></details>\\n<details><summary>ऑपरेटर क्या देखते हैं?</summary><p>ट्रांसक्रिप्ट आपकी टीम की भाषा में रहते हैं, और मूल संदेश अनुवाद के साथ सुरक्षित रहता है।</p></details>\\n<p>बातचीत के बीच में भाषा बदलती Gaia की एक झलक:</p>\\n<img src=\\"https://picsum.photos/seed/wexio-lang/1024/576\\" alt=\\"कई भाषाओं में जवाब देती Gaia\\" />"},"demo-news-4":{"title":"बातचीत सीधे Slack में भेजें","excerpt":"किसी भी इनकमिंग वेबहुक को Slack चैनल से जोड़ें। कोई जोड़ने वाला कोड नहीं।","body":"## दो क्लिक में जोड़ें\\n\\n**इंटीग्रेशन → Slack** पर जाएँ, *कनेक्ट* दबाएँ और अनुमतियाँ मंज़ूर करें। वह चैनल चुनें जहाँ नई बातचीतें आनी चाहिए - ज़्यादातर टीमें `#support` इस्तेमाल करती हैं।\\n\\n## आपको क्या मिलेगा\\n\\n- चैट शुरू होते ही Slack संदेश, इनबॉक्स का लिंक साथ में।\\n- ऑपरेटर के जवाब मूल संदेश के नीचे थ्रेड में।\\n- Slack से ही जवाब दें और हम उसे रीयल टाइम में विज़िटर तक पहुँचा देंगे।\\n\\n## वेबहुक भी\\n\\nक्या आप पहले से अपने सिस्टम से इवेंट भेज रहे हैं? किसी भी वेबहुक को अपने Slack चैनल की ओर मोड़ें और कस्टम इंटीग्रेशन को पूरी तरह छोड़ दें।"},"demo-news-5":{"title":"इनबॉक्स 2.0: बिना माउस के छँटाई","excerpt":"असाइन करने, स्नूज़ करने और हल करने के नए शॉर्टकट - सब कीबोर्ड से।","body":"<p>इनबॉक्स 2.0 कीबोर्ड-प्रथम है। आप जो कर रहे हैं उसके हिसाब से समूहित चीट शीट:</p>\\n<div data-type=\\"tabs\\">\\n<div data-type=\\"tab\\"><div data-tab-label>नेविगेट</div><ul><li><code>j</code> / <code>k</code> - अगली / पिछली बातचीत</li><li><code>g</code> फिर <code>i</code> - इनबॉक्स पर जाएँ</li></ul></div>\\n<div data-type=\\"tab\\"><div data-tab-label>कार्रवाई</div><ul><li><code>e</code> - हल करें</li><li><code>a</code> - मुझे असाइन करें</li><li><code>s</code> - स्नूज़ करें</li></ul></div>\\n<div data-type=\\"tab\\"><div data-tab-label>लिखें</div><ul><li><code>Cmd+Enter</code> - भेजें</li><li><code>/</code> - सहेजे हुए जवाब</li><li><code>Cmd+K</code> - कमांड पैलेट</li></ul></div>\\n</div>\\n<p>नया डिज़ाइन किया इनबॉक्स - सब कुछ एक कुंजी की पहुँच में:</p>\\n<img src=\\"https://picsum.photos/seed/wexio-inbox/1024/576\\" alt=\\"नया डिज़ाइन किया कीबोर्ड-प्रथम इनबॉक्स\\" />"},"demo-news-6":{"title":"खुद से डेटा एक्सपोर्ट और हटाना","excerpt":"विज़िटर के डेटा अनुरोधों को एक क्लिक में संभालें। शुरू से GDPR के लिए तैयार।","body":"## एक्सपोर्ट\\n\\nकिसी भी विज़िटर की प्रोफ़ाइल से **डेटा एक्सपोर्ट करें** दबाएँ और हमारे पास उसके हर संदेश, इवेंट और एट्रिब्यूट का JSON बंडल बन जाएगा। यह तुरंत डाउनलोड होता है और अनुरोध आपके रिकॉर्ड के लिए दर्ज हो जाता है।\\n\\n## हटाएँ\\n\\n**डेटा हटाएँ** विज़िटर को हटाता है और उसके संदेशों को इनबॉक्स, खोज और उसी वेबहुक ब्रिज से जुड़े किसी भी CRM से मिटा देता है। कार्रवाई दर्ज होती है और वापस नहीं ली जा सकती।\\n\\n## आपके DPO के लिए\\n\\n- हर एक्सपोर्ट और हटाने पर टाइमस्टैम्प और ज़िम्मेदार व्यक्ति दर्ज होता है।\\n- रिटेंशन अवधि हर वर्कस्पेस के लिए कॉन्फ़िगर की जा सकती है।\\n- डेटा-प्रोसेसिंग समझौता अनुरोध पर उपलब्ध है।"},"demo-news-7":{"title":"मोबाइल SDK बीटा: iOS और Android","excerpt":"वही बातचीत अपने नेटिव ऐप में लाएँ। बीटा सीटें अब खुली हैं।","body":"## एक बातचीत, हर जगह\\n\\nआपकी वेबसाइट पर चैट शुरू करने वाला विज़िटर उसे आपके ऐप में साइन-इन रहकर पूरे इतिहास के साथ जारी रख सकता है। वही Gaia, वही ऑपरेटर, वही इनबॉक्स।\\n\\n## बीटा में क्या है\\n\\n- SwiftUI और Jetpack Compose के लिए नेटिव लॉन्चर।\\n- नए जवाबों के लिए पुश नोटिफ़िकेशन।\\n- ऑफ़लाइन कतार, ताकि कनेक्शन लौटते ही संदेश भेज दिए जाएँ।\\n\\n## जुड़ें\\n\\nहम हर हफ़्ते मुट्ठी भर टीमों को जोड़ रहे हैं। अपने प्लेटफ़ॉर्म और मासिक सक्रिय उपयोगकर्ताओं के मोटे अनुमान के साथ यहाँ जवाब दें और हम आपको एक कुंजी भेज देंगे।\\n\\n> बीटा का मतलब है कुछ खुरदुरे किनारे। हम हर हफ़्ते सुधार जारी करते हैं और हर बग रिपोर्ट पढ़ते हैं।"},"demo-news-8":{"title":"देखें कि AI के कौन से जवाब सचमुच काम आए","excerpt":"ट्रैक करें कि Gaia का हर जवाब समाधान, हैंडऑफ़ या विज़िटर के चले जाने में से किसकी ओर ले गया।","body":"## नया व्यू\\n\\n**एनालिटिक्स → AI नतीजे** Gaia के हर जवाब को इस आधार पर बाँटता है कि उसके बाद क्या हुआ:\\n\\n- **हल हुआ** - विज़िटर को जो चाहिए था मिल गया और वह संतुष्ट होकर गया।\\n- **हैंडऑफ़ हुआ** - Gaia ने बातचीत किसी इंसान को सौंप दी।\\n- **छोड़ गया** - विज़िटर ने समाधान के बिना विजेट बंद कर दिया।\\n\\n## हर लेख की अंतर्दृष्टि\\n\\nकिसी भी सहायता लेख में जाकर देखें कि Gaia उसका कितनी बार हवाला देती है और क्या वे हवाले समाधान तक पहुँचते हैं। ज़्यादा ट्रैफ़िक वाले लेख पर कम समाधान का आम तौर पर मतलब होता है कि सामग्री को दोबारा लिखना है, AI को नहीं।\\n\\n## उस पर कार्रवाई करें\\n\\nछोड़ जाने की दर के हिसाब से छाँटें ताकि वे सवाल मिलें जिनमें Gaia को सबसे ज़्यादा दिक़्क़त होती है, फिर कमी भरने के लिए कोई फ़्लो या ज़्यादा सटीक लेख जोड़ें।"},"tags":{"events":"इवेंट","product":"प्रोडक्ट","release":"रिलीज़","ai":"AI","languages":"भाषाएँ","integrations":"इंटीग्रेशन","slack":"Slack","inbox":"इनबॉक्स","privacy":"गोपनीयता","security":"सुरक्षा","mobile":"मोबाइल","beta":"बीटा","analytics":"एनालिटिक्स"},"categories":{"company":"कंपनी","product":"प्रोडक्ट","engineering":"इंजीनियरिंग"}}'),n=JSON.parse('{"categories":{"demo-cat-getting-started":{"title":"शुरुआत करें","description":"विजेट इंस्टॉल करें और अपनी पहली बातचीत सेट करें।"},"demo-cat-automation":{"title":"ऑटोमेशन","description":"फ़्लो, ट्रिगर और AI का ऑटो-रिप्लाई।"},"demo-cat-integrations":{"title":"इंटीग्रेशन","description":"अपना CRM, Slack और CMS जोड़ें।"},"demo-cat-billing":{"title":"बिलिंग और प्लान","description":"कीमत के स्तर, इनवॉइस और सीट प्रबंधन।"}},"articles":{"demo-article-install":{"title":"अपनी साइट पर Wexio विजेट इंस्टॉल करें","excerpt":"30 सेकंड का एक स्निपेट जिसे आप समापन </body> टैग से पहले चिपकाते हैं।","body":"## लोडर स्क्रिप्ट जोड़ें\\n\\nइस स्निपेट को हर उस पेज पर चिपकाएँ जहाँ आप विजेट दिखाना चाहते हैं:\\n\\n```html\\n<script\\n  src=\\"https://cdn.wexio.io/widget/loader.js\\"\\n  data-public-key=\\"pk_live_YOUR_KEY\\"\\n><\/script>\\n```\\n\\nलोडर नीचे दाएँ कोने में एक तैरता हुआ लॉन्चर जोड़ता है। चैट पैनल खोलने के लिए उस पर क्लिक करें।\\n\\n## इंस्टॉलेशन जाँचें\\n\\n- उस पेज पर जाएँ जिसमें स्निपेट है।\\n- ब्राउज़र कंसोल खोलें।\\n- आपको `[wexio] widget mounted` दिखना चाहिए।\\n\\n## रूप-रंग अपने अनुसार बदलें\\n\\nविजेट आपके डैशबोर्ड से ब्रांड के रंग पढ़ता है। उन्हें **सेटिंग्स → ब्रांड** में अपडेट करें।\\n\\n> मदद चाहिए? नीचे \\"अभी भी मदद चाहिए? हमें संदेश भेजें\\" पर टैप करें और हम आपको रास्ता दिखाएँगे।"},"demo-article-flows":{"title":"अपना पहला ऑटोमेशन फ़्लो बनाएँ","excerpt":"खींचें, छोड़ें और पाँच मिनट से कम में स्वागत बॉट लॉन्च करें।","body":"## फ़्लो क्या है?\\n\\nफ़्लो बातचीत के चरणों - सवाल, जवाब और शर्तों - का एक छोटा पेड़ है जो हर बार तब चलता है जब कोई विज़िटर किसी ट्रिगर से मेल खाता है।\\n\\n## तीन तरह के ट्रिगर\\n\\n1. **विज़िटर ने विजेट खोला** - पहली बार आने वालों का स्वागत करें।\\n2. **विज़िटर ने सवाल पूछा** - Gaia (AI) जवाब देने की कोशिश करती है; न दे पाए तो फ़्लो संभाल लेता है।\\n3. **वेबहुक मिला** - आपका CMS या ई-कॉमर्स प्लेटफ़ॉर्म इवेंट भेजता है; फ़्लो सही चैट में शुरू हो जाता है।\\n\\n## सर्वोत्तम तरीक़े\\n\\n- पहले जवाब 80 अक्षरों से कम रखें।\\n- खुले टेक्स्ट वाले सवाल की जगह 2-3 क्विक-रिप्लाई चिप दें।\\n- हमेशा बाहर निकलने का रास्ता दें - *\\"किसी इंसान से बात करें\\"*।"},"demo-article-slack":{"title":"चैट Slack में फ़ॉरवर्ड करें","excerpt":"हर नई बातचीत को अपनी पसंद के Slack चैनल में प्रतिबिंबित करें।","body":"## अपना वर्कस्पेस जोड़ें\\n\\n**इंटीग्रेशन → Slack** में *कनेक्ट* पर क्लिक करें। आप Slack की OAuth स्क्रीन पर पहुँचेंगे - माँगी गई अनुमतियाँ (`chat:write`, `channels:read`) मंज़ूर करें।\\n\\n## चैनल चुनें\\n\\nअधिकृत करने के बाद लक्ष्य चैनल चुनें (या `#support` जैसा नया बनाएँ)।\\n\\n## क्या फ़ॉरवर्ड होता है\\n\\n- शुरुआती संदेश, wexio इनबॉक्स के सीधे लिंक के साथ।\\n- ऑपरेटर के जवाब थ्रेड संदेशों के रूप में।\\n- विज़िटर के जवाब SSE ब्रिज के ज़रिए रीयल टाइम में।\\n\\n## उलटी दिशा\\n\\nऑपरेटर Slack *से* जवाब दे सकते हैं - wexio Slack थ्रेड के जवाब सुनता है और उन्हें विजेट में वापस भेज देता है।"},"demo-article-billing":{"title":"अपना प्लान और बिलिंग विवरण अपडेट करें","excerpt":"प्लान बदलें, कार्ड बदलें या इनवॉइस डाउनलोड करें।","body":"## प्लान\\n\\n- **Free** - 1 विजेट, बुनियादी सुविधाएँ, \\"Powered by Wexio\\" बैज।\\n- **Standard** - असीमित विजेट, ऑटोमेशन, इंटीग्रेशन।\\n- **Enterprise** - व्हाइट-लेबल, SLA, समर्पित सपोर्ट।\\n\\n## प्लान बदलें\\n\\n**सेटिंग्स → बिलिंग → प्लान बदलें**। अपग्रेड तुरंत लागू होते हैं; डाउनग्रेड मौजूदा चक्र के अंत में लागू होते हैं।\\n\\n## इनवॉइस\\n\\n**बिलिंग → इतिहास** से हर इनवॉइस PDF के रूप में डाउनलोड करें। हम हर नवीनीकरण पर ईमेल से एक प्रति भी भेजते हैं।"},"demo-article-theme":{"title":"विजेट की थीम अपने अनुसार बदलें","excerpt":"विजेट को अपने ब्रांड से मिलाएँ - रंग, गोलाई, डार्क मोड।","body":"## ब्रांड के रंग\\n\\n**सेटिंग्स → ब्रांड** में तय करें:\\n\\n- **प्राथमिक** - लॉन्चर, भेजें बटन और फ़ोकस रिंग को नियंत्रित करता है।\\n- **पृष्ठभूमि** - पैनल की सतह (लाइट) और डार्क मोड की जोड़ी।\\n\\n## गोलाई\\n\\nज़्यादा तीखे या नरम रूप के लिए `sm`, `md`, `lg` में से चुनें। बदलाव हर पेज के हर विजेट पर तुरंत लागू होता है।\\n\\n## डार्क मोड\\n\\nडिफ़ॉल्ट = विज़िटर की सिस्टम पसंद का पालन करें। अगर आपकी साइट खुद डार्क मोड को सपोर्ट नहीं करती, तो इसे **हमेशा लाइट** या **हमेशा डार्क** पर तय करें।"},"demo-article-handoff":{"title":"Gaia से इंसानी ऑपरेटर को सौंपें","excerpt":"जब AI काफ़ी न हो - विज़िटर को किसी साथी तक पहुँचाएँ।","body":"## ट्रिगर\\n\\nGaia अपने आप हैंडऑफ़ करती है जब:\\n\\n- विज़िटर *\\"किसी इंसान से बात करें\\"* लिखता है (या उसका कोई स्थानीय रूप)।\\n- एक ही सवाल बिना समाधान के दो बार पूछा जाए।\\n- विज़िटर का इरादा किसी रूटिंग नियम से मेल खाए (जैसे बिलिंग → फ़ाइनेंस टीम)।\\n\\n## रूटिंग\\n\\nकुछ इरादों को ख़ास टीमों या ऑपरेटरों तक भेजने के लिए **रूटिंग → नियम** सेट करें। राउंड-रॉबिन और सबसे कम लोड वाले, दोनों समर्थित हैं।\\n\\n## काम के घंटों के बाहर\\n\\nअगर कोई ऑपरेटर ऑनलाइन नहीं है, तो Gaia यह दिखावा करने की जगह कि कोई उपलब्ध है, कॉलबैक या ईमेल-हैंडऑफ़ फ़ॉर्म पेश करती है।"},"demo-article-crm":{"title":"बातचीत को अपने CRM से सिंक करें","excerpt":"हर चैट HubSpot, Salesforce या Pipedrive में भेजें।","body":"## समर्थित CRM\\n\\n- HubSpot (OAuth)\\n- Salesforce (OAuth)\\n- Pipedrive (API टोकन)\\n- वेबहुक के ज़रिए कस्टम\\n\\n## क्या सिंक होता है\\n\\n- नई बातचीतें एक संपर्क (अगर पहले से न हो) और एक नोट बनाती हैं।\\n- ऑपरेटर के जवाब संपर्क की टाइमलाइन में जुड़ते हैं।\\n- wexio में लगाए गए टैग CRM में दिखते हैं।\\n\\n## दोतरफ़ा\\n\\nCRM में जोड़े गए ऑपरेटर नोट वेबहुक रिसीवर के ज़रिए wexio में वापस आ सकते हैं - देखें *इंटीग्रेशन → वेबहुक → इनबाउंड*।"},"demo-article-shortcuts":{"title":"ऑपरेटर के कीबोर्ड शॉर्टकट","excerpt":"दोगुनी तेज़ी से छँटाई करें - माउस के बिना।","body":"## इनबॉक्स नेविगेशन\\n\\n- `j` / `k` - अगली / पिछली बातचीत\\n- `e` - हल करें\\n- `a` - मुझे असाइन करें\\n- `s` - स्नूज़ करें\\n\\n## कंपोज़र\\n\\n- `Cmd+Enter` - भेजें\\n- `/` - सहेजे हुए जवाबों का चयनकर्ता खोलें\\n- `Cmd+K` - कमांड पैलेट (सब कुछ)\\n\\n## सुझाव\\n\\nडैशबोर्ड में किसी भी बटन पर कर्सर ले जाएँ - टूलटिप उसका शॉर्टकट दिखाता है।"}},"tags":{"setup":"सेटअप","install":"इंस्टॉल","automation":"ऑटोमेशन","flows":"फ़्लो","integrations":"इंटीग्रेशन","slack":"Slack","billing":"बिलिंग","plans":"प्लान","design":"डिज़ाइन","ai":"AI","crm":"CRM","productivity":"उत्पादकता","inbox":"इनबॉक्स"}}'),r={visitorName:`आप`,messages:{"m-demo-1":{text:`नमस्ते 👋 मैं Gaia हूँ, Wexio की AI। मैं आपकी क्या मदद कर सकती हूँ?`,ageLabel:`9:41 पूर्वाह्न`,buttons:[`कीमत कैसे तय होती है?`,`यह क्या कर सकता है?`,`किसी इंसान से बात करें`]},"m-demo-2":{text:`क्या आप दिखा सकती हैं कि विजेट कैसा दिखता है?`,ageLabel:`9:41 पूर्वाह्न`},"m-demo-3":{text:``,ageLabel:`9:42 पूर्वाह्न`,mediaAlts:[`प्रोडक्ट का स्क्रीनशॉट`]},"m-demo-4":{text:``,ageLabel:`9:42 पूर्वाह्न`,mediaAlts:[`घूमता हुआ ग्लोब`]},"m-demo-5":{text:`बढ़िया! 😄 ये हमारी टीम की कुछ झलकियाँ हैं।`,ageLabel:`9:43 पूर्वाह्न`},"m-demo-6":{text:`डैशबोर्ड की कुछ ख़ास बातें`,ageLabel:`9:43 पूर्वाह्न`,mediaAlts:[`डैशबोर्ड का अवलोकन`,`एनालिटिक्स`,`इनबॉक्स`,`रिपोर्ट`]},"m-demo-7":{text:``,ageLabel:`9:44 पूर्वाह्न`,mediaAlts:[`संक्षिप्त वॉकथ्रू`]},"m-demo-8":{text:``,ageLabel:`9:44 पूर्वाह्न`,mediaAlts:[`वॉइस नोट`]},"m-demo-9":{text:``,ageLabel:`9:45 पूर्वाह्न`,mediaAlts:[`शुरुआत की गाइड`]},"m-demo-9b":{text:``,ageLabel:`9:45 पूर्वाह्न`,mediaAlts:[`Wexio इंटीग्रेशन`]},"m-demo-10":{text:`क्या आप इसे खुद आज़माने के लिए तैयार हैं?`,ageLabel:`9:45 पूर्वाह्न`,buttons:[`सैंडबॉक्स खोलें`,`कॉल बुक करें`,`चैट जारी रखें`]}}},i={messengerDescription:`हमारी टीम भी मदद कर सकती है`,messengerMessage:`नमस्ते 👋 हमसे कुछ भी पूछें, या कोई त्वरित कार्रवाई चुनें।`},a={welcome:{system:`अब आप हमारी AI सहायक Gaia से चैट कर रहे हैं।`,hint:`सुझाव: कभी भी फ़ाइल जोड़ें या वॉइस नोट रिकॉर्ड करें।`,greeting:`नमस्ते 👋 मैं Gaia हूँ, Wexio की AI। कुछ भी पूछिए, या शुरू करने के लिए कोई क्विक एक्शन चुनिए।`},replies:{pricing:{text:`Wexio एक विजेट के लिए मुफ़्त है; सशुल्क प्लान $39/माह से शुरू होते हैं और ऑटोमेशन, इंटीग्रेशन और व्हाइट-लेबल अनलॉक करते हैं।`,planBtn:`प्लान के स्तर दिखाएँ`,salesBtn:`सेल्स से बात करें`},gaia:{text:`Gaia वह AI एजेंट है जो विज़िटर के सवालों के तुरंत जवाब देती है। वह आपके सहायता लेखों से सीखती है और जब मदद नहीं कर पाती तो किसी इंसान को सौंप देती है।`,handoffBtn:`हैंडऑफ़ कैसे काम करता है?`},human:{text:`बिल्कुल - मैं टीम के Alex को जोड़ रही हूँ। वे काम के घंटों में कुछ ही मिनटों में जवाब देंगे।`},fallback:{text:`समझ गई - मैं इसे देखकर थोड़ी देर में आपके पास लौटती हूँ।`},voice:{text:`आपका वॉइस नोट मिल गया - मैं इसे देखकर आपके पास लौटती हूँ।`}}},o={main:`क्या आप इसे खुद आज़माने के लिए तैयार हैं?`,billing:`धन्यवाद! मैंने आपका इनवॉइस वाला सवाल बिलिंग टीम को भेज दिया है।`,integrations:`मैं WhatsApp को अपने खाते से कैसे जोड़ूँ?`},s={recentMessage:e,news:t,help:n,conversation:r,playgroundDefaults:i,messenger:a,threads:o};export{r as conversation,s as default,n as help,a as messenger,t as news,i as playgroundDefaults,e as recentMessage,o as threads};
